package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time so tests can control the passage of time.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// TokenBucket is a concurrency-safe token bucket.
type TokenBucket struct {
	mu       sync.Mutex
	capacity int
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
	clock    Clock
}

// New returns a full TokenBucket. capacity must be > 0, rate must be > 0,
// and clock must be non-nil (pass nil to use the system clock).
func New(capacity int, rate float64, clock Clock) (*TokenBucket, error) {
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	if clock == nil {
		clock = realClock{}
	}
	return &TokenBucket{
		capacity: capacity,
		rate:     rate,
		tokens:   float64(capacity),
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// AllowN reports whether n tokens can be consumed right now.
// n <= 0 always returns true. n > capacity always returns false.
func (b *TokenBucket) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked()
	if n > b.capacity {
		return false
	}
	if b.tokens >= float64(n) {
		b.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token can be consumed right now.
func (b *TokenBucket) Allow() bool { return b.AllowN(1) }

func (b *TokenBucket) refillLocked() {
	now := b.clock.Now()
	elapsed := now.Sub(b.last).Seconds()
	if elapsed <= 0 {
		return
	}
	b.tokens += elapsed * b.rate
	if max := float64(b.capacity); b.tokens > max {
		b.tokens = max
	}
	b.last = now
}
