package ratelimit

import (
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{t: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.t = c.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	clk := newFakeClock()
	cases := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"valid", 10, 1, clk, false},
		{"nil clock uses system", 10, 1, nil, false},
		{"zero capacity", 0, 1, clk, true},
		{"negative capacity", -1, 1, clk, true},
		{"zero rate", 10, 0, clk, true},
		{"negative rate", 10, -2, clk, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			b, err := New(tc.capacity, tc.rate, tc.clock)
			if tc.wantErr && err == nil {
				t.Fatal("expected error, got nil")
			}
			if !tc.wantErr && err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if !tc.wantErr && b == nil {
				t.Fatal("expected bucket, got nil")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	cases := []struct {
		name    string
		cap     int
		rate    float64
		advance time.Duration
		n       int
		want    bool
	}{
		{"full bucket allows one", 10, 1, 0, 1, true},
		{"allows up to capacity", 10, 1, 0, 10, true},
		{"rejects above capacity", 10, 1, 0, 11, false},
		{"zero n always true", 10, 1, 0, 0, true},
		{"negative n always true", 10, 1, 0, -3, true},
		{"refills over time", 10, 1, 5 * time.Second, 5, true},
		{"refill insufficient", 10, 2, time.Second, 3, false},
		{"refill exact", 10, 2, time.Second, 2, true},
		{"no refill without advance", 10, 100, 0, 11, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			clk := newFakeClock()
			b, err := New(tc.cap, tc.rate, clk)
			if err != nil {
				t.Fatal(err)
			}
			clk.Advance(tc.advance)
			if got := b.AllowN(tc.n); got != tc.want {
				t.Fatalf("AllowN(%d) = %v, want %v", tc.n, got, tc.want)
			}
		})
	}
}

func TestAllowNConsumesTokens(t *testing.T) {
	clk := newFakeClock()
	b, err := New(5, 1, clk)
	if err != nil {
		t.Fatal(err)
	}
	if !b.AllowN(4) {
		t.Fatal("expected 4 tokens to be allowed")
	}
	if b.AllowN(2) {
		t.Fatal("expected only 1 token remaining")
	}
	if !b.AllowN(1) {
		t.Fatal("expected final token to be allowed")
	}
	if b.AllowN(1) {
		t.Fatal("expected bucket to be empty")
	}
}

func TestAllowNConcurrent(t *testing.T) {
	clk := newFakeClock()
	b, err := New(100, 0.0001, clk)
	if err != nil {
		t.Fatal(err)
	}
	var allowed atomic.Int32
	var wg sync.WaitGroup
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if b.Allow() {
				allowed.Add(1)
			}
		}()
	}
	wg.Wait()
	if got := allowed.Load(); got != 100 {
		t.Fatalf("allowed = %d, want 100", got)
	}
}
